"""mpl_toolkits.axisartist.grid_finder — grid-line and tick finder
for curvilinear axes. Walks the four bounding edges of the data
window to find where the user's gridlines (lon/lat in geo axes,
r/θ in polar) cross.
"""

import numpy as _np


class GridFinder:
    """Driver that combines an extreme-finder, two locators, and two
    tick-formatters into a coherent grid-position computation. Used by
    GridHelperCurveLinear to produce gridline coordinates."""

    def __init__(self, transform, extreme_finder=None, grid_locator1=None,
                  grid_locator2=None, tick_formatter1=None, tick_formatter2=None):
        self.transform = transform
        self.extreme_finder = extreme_finder or ExtremeFinderSimple(20, 20)
        self.grid_locator1 = grid_locator1 or MaxNLocator(10)
        self.grid_locator2 = grid_locator2 or MaxNLocator(10)
        self.tick_formatter1 = tick_formatter1 or FormatterPrettyPrint()
        self.tick_formatter2 = tick_formatter2 or FormatterPrettyPrint()

    def get_grid_info(self, x1, y1, x2, y2):
        """Compute the gridline positions over the window
        ``[(x1, y1), (x2, y2)]``. Returns the same nested dict shape
        upstream uses."""
        extremes = self.extreme_finder(self.transform, x1, y1, x2, y2)
        lon_min, lon_max, lat_min, lat_max = extremes
        lon_levels, lon_n, lon_factor = self.grid_locator1(lon_min, lon_max)
        lat_levels, lat_n, lat_factor = self.grid_locator2(lat_min, lat_max)
        lon_labels = self.tick_formatter1(None, lon_factor, lon_levels)
        lat_labels = self.tick_formatter2(None, lat_factor, lat_levels)
        return {
            'extremes': extremes,
            'lon_lines': lon_levels,
            'lat_lines': lat_levels,
            'lon_labels': lon_labels,
            'lat_labels': lat_labels,
            'lon_factor': lon_factor,
            'lat_factor': lat_factor,
        }


class MaxNLocator:
    """Pick ≤ nbins evenly-spaced tick locations from a "nice" ladder."""

    def __init__(self, nbins=10, steps=None):
        self.nbins = int(nbins)
        self.steps = tuple(steps) if steps else (1, 2, 2.5, 5, 10)

    def __call__(self, v1, v2):
        span = abs(v2 - v1)
        if span == 0:
            return [v1], 1, 1.0
        raw = span / max(self.nbins, 1)
        mag = 10 ** _np.floor(_np.log10(raw))
        normalized = raw / mag
        step = next((s for s in self.steps if s >= normalized),
                     self.steps[-1]) * mag
        lo = _np.floor(v1 / step) * step
        hi = _np.ceil(v2 / step) * step
        values = list(_np.arange(lo, hi + step * 0.5, step))
        return values, len(values), 1.0


class FixedLocator:
    """Use a user-supplied fixed tick list."""

    def __init__(self, locs):
        self.locs = list(locs)

    def __call__(self, v1, v2):
        out = [v for v in self.locs if v1 <= v <= v2]
        return out, len(out), 1.0


class FormatterPrettyPrint:
    """Default formatter — emits ``'{value:g}'`` for each tick."""

    def __init__(self, useMathText=False):
        self.useMathText = useMathText

    def __call__(self, direction, factor, values):
        return [f'${v * factor:g}$' if self.useMathText
                else f'{v * factor:g}' for v in values]


class DictFormatter:
    """Lookup formatter — use ``mapping`` to translate each value to
    its label; falls back to ``formatter`` for unmapped values."""

    def __init__(self, mapping, formatter=None):
        self._mapping = dict(mapping)
        self._fallback = formatter or FormatterPrettyPrint()

    def __call__(self, direction, factor, values):
        out = []
        for v in values:
            if v in self._mapping:
                out.append(self._mapping[v])
            else:
                out.append(self._fallback(direction, factor, [v])[0])
        return out


class ExtremeFinderSimple:
    """Find the extremes of the data window by transforming ``nx × ny``
    sample points across the window and taking min/max."""

    def __init__(self, nx, ny):
        self.nx = int(nx)
        self.ny = int(ny)

    def __call__(self, transform_xy, x1, y1, x2, y2):
        xs = _np.linspace(x1, x2, self.nx)
        ys = _np.linspace(y1, y2, self.ny)
        XX, YY = _np.meshgrid(xs, ys)
        # transform_xy may be a callable or an Affine2D-like.
        try:
            if hasattr(transform_xy, 'transform'):
                pts = transform_xy.transform(
                    _np.column_stack([XX.ravel(), YY.ravel()]))
                u, v = pts[:, 0], pts[:, 1]
            else:
                u, v = transform_xy(XX.ravel(), YY.ravel())
        except Exception:
            # Identity fallback.
            u, v = XX.ravel(), YY.ravel()
        return (float(_np.nanmin(u)), float(_np.nanmax(u)),
                float(_np.nanmin(v)), float(_np.nanmax(v)))
